import {copy} from './music.js';
import {normalizeControls,compareProjects} from './composition.js';
import {candidateMatches,compareCandidates,createOfflineAlternatives,normalizeCandidate,projectFingerprint} from './candidates.js';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const source=c=>c.source==='llm'?'外部模型':'离线规则',count=p=>p.tracks.reduce((n,t)=>n+t.notes.length,0);
const parameters=c=>c.controls?`密度 ${c.controls.density} · 复杂 ${c.controls.complexity} · 能量 ${c.controls.energy} · 人性化 ${c.controls.humanize} · 种子 ${c.controls.seed}`:'未启用调色盘';
const rows=diff=>`<div class="candidate-diff-list">${diff.tracks.map(t=>`<div class="candidate-diff-row ${t.changed?'changed':''}"><strong>${escape(t.name)}</strong><span>${t.before} → ${t.after}</span><small>${t.changed?`＋${t.added} / －${t.removed} / 修改 ${t.modified}${t.soundChanged?' · 音色变化':''}`:'保持原样'}</small></div>`).join('')}</div>`;
export function candidateComparisonReport(a,b){const diff=compareCandidates(a,b);return{format:'sprout-candidate-comparison',version:1,baseline:{id:a.before.id,name:a.before.name,bars:a.before.bars,bpm:a.before.bpm,key:a.before.key,notes:count(a.before)},direction:'A → B',a:{id:a.id,label:a.label,source:a.source,prompt:a.prompt,context:copy(a.context),...(a.controls?{controls:copy(a.controls)}:{})},b:{id:b.id,label:b.label,source:b.source,prompt:b.prompt,context:copy(b.context),...(b.controls?{controls:copy(b.controls)}:{})},differences:diff,interpretation:'按相同音高与拍位置配对；ID 不计变化。修改含长度、力度与微偏移。不是音乐质量评分，也没有播放音频。'}}
export function createCandidateUI({store,getProject,getCandidate,getContext,getControls,isBusy,setBusy,stage,modal,toast,download,projectFilename,onChange}){
 function refresh(){const button=$('#candidate-shelf');button.textContent=`候选架 ${store.entries.length}`;button.title=store.available?'在本浏览器保留候选，先对比再应用':'候选架存储不可用，点击重新读取';$('#generate-alternatives').disabled=isBusy()||!store.available}
 function changed(){refresh();onChange()}
 function stageSaved(id){const c=store.get(id);if(!candidateMatches(c,getProject()))throw Error('工程与这版原稿不同，不能应用旧候选。可下载或查看差异，或撤销回原稿后再打开');stage(c);$('#modal').close();toast('已打开为候选；工作区尚未改变，也没有开始播放。')}
 function exportCandidate(id){const c=store.get(id);download(JSON.stringify(c.project,null,2),projectFilename(c.project)+' · '+c.label.replace(/[<>:"/\\|?*]/g,'_')+'.sprout','application/json');toast('候选工程已单独下载，当前工作区保持。')}
 function shelf(){const list=store.list(getProject()),size=store.size();
  modal('候选架 · 保留几版，再决定',`<div class="candidate-shelf-form"><p>这里保留的是完整候选和它的原稿，不是已经应用的工作区。打开 / 比较 / 下载不会播放声音；与当前原稿完全相同，才允许打开为待应用候选。撤销回原稿后可再次选择。</p><div class="version-stats"><span>${list.length} / 6 版</span><span>${(size/1024).toFixed(0)} KiB / 8 MiB</span><span>仅本浏览器 · 非云备份</span></div>${!store.available?`<div class="modal-notice candidate-stale">存储不可用：${escape(store.error||'请重新读取')}。没有覆盖旧数据；当前工作区与直接生成仍可使用。</div>`:''}<div class="candidate-shelf-list">${list.map(c=>`<article class="shelf-card ${c.matches?'':'stale'}"><header><strong>${escape(c.label)}</strong><span>${source(c)}</span></header><small>${escape(c.context.scopeLabel)} · ${c.notesBefore} → ${c.notesAfter} 音符</small><small>${escape(parameters(c))}</small><p class="shelf-status">${c.matches?'原稿与工作区一致 · 可打开':'原稿已改变 · 只查看或下载，不覆盖工作区'}</p><div class="shelf-actions"><button class="accent compact" data-shelf-stage="${c.id}" ${c.matches?'':'disabled'}>打开为候选</button><button class="quiet compact" data-shelf-review="${c.id}">与原稿比较</button><button class="quiet compact" data-shelf-export="${c.id}">下载工程</button><button class="quiet compact" data-shelf-rename="${c.id}">改名</button><button class="quiet compact" data-shelf-remove="${c.id}">移除</button></div></article>`).join('')||'<div class="candidate-empty"><h3>先保留喜欢的版本</h3><p>助手生成后点“保留这版”；或点“规则三版”，从同一原稿生成留白 / 适中 / 活力三个方案。单版真实模型的结果也能保留，但不会自动调用模型。</p></div>'}</div>${list.length>=2?`<div class="shelf-compare"><h3>选两版 · 逐音 A/B 对比</h3><div class="shelf-compare-fields"><label for="compare-a">A（作为比较起点）<select id="compare-a">${list.map(c=>`<option value="${c.id}">${escape(c.label)}</option>`).join('')}</select></label><label for="compare-b">B（与 A 比较）<select id="compare-b">${list.map((c,i)=>`<option value="${c.id}" ${i===1?'selected':''}>${escape(c.label)}</option>`).join('')}</select></label></div><button class="accent" id="shelf-compare">比较两版，不播放</button><p>两版必须基于同一完整原稿；改变密度不代表一定更好，没有自动音乐质量评分。</p></div>`:''}<div id="shelf-error" class="export-progress" role="status"></div><div class="modal-notice">最多 6 版 / 8 MiB，不自动淘汰已有候选；存储成功才报告保留。删除只移除候选架记录，不删除工作区或已有工程文件。本页面可撤销最近一次移除，刷新后这一步移除撤销不保留。重要候选请先单独下载。</div></div>`,'<button class="quiet" id="shelf-reload">重新读取</button>'+ (store.lastRemoved?'<button class="quiet" id="shelf-undo-remove">撤销最近移除</button>':'')+'<button class="accent" data-close>返回工作台</button>');
  const run=fn=>async()=>{try{await fn();changed()}catch(e){const error=$('#shelf-error');if(error)error.textContent=e.message;else toast(e.message)}};
  $$('[data-shelf-stage]').forEach(b=>b.onclick=run(()=>stageSaved(b.dataset.shelfStage)));$$('[data-shelf-export]').forEach(b=>b.onclick=run(()=>exportCandidate(b.dataset.shelfExport)));$$('[data-shelf-review]').forEach(b=>b.onclick=()=>review(b.dataset.shelfReview));$$('[data-shelf-rename]').forEach(b=>b.onclick=()=>rename(b.dataset.shelfRename));$$('[data-shelf-remove]').forEach(b=>b.onclick=run(async()=>{await store.remove(b.dataset.shelfRemove);shelf();toast('仅移除了候选架中的这版；可在本页面撤销最近移除。')}));
  $('#shelf-reload').onclick=run(async()=>{await store.reload();shelf();toast('已重新读取候选架，没有改变工作区。')});if($('#shelf-undo-remove'))$('#shelf-undo-remove').onclick=run(async()=>{await store.undoRemove();shelf()});if($('#shelf-compare'))$('#shelf-compare').onclick=run(()=>comparison($('#compare-a').value,$('#compare-b').value));
 }
 function review(id){const c=store.get(id),diff=compareProjects(c.before,c.project);modal('保留候选 · 与它的原稿比较',`<div class="candidate-shelf-form"><h3>${escape(c.label)}</h3><p>${source(c)} · ${escape(c.context.scopeLabel)}</p><p>${escape(c.prompt)}</p><p>${escape(parameters(c))}</p><div class="version-stats"><span>${diff.notesBefore} → ${diff.notesAfter} 音符</span><span>${diff.changedTracks} 轨变化</span><span>＋${diff.added} / －${diff.removed} / 修改 ${diff.modified}</span></div>${rows(diff)}<div class="modal-notice">比较起点是这版保存时的原稿，不是后来编辑的工作区。全局变化：${diff.globals.length?diff.globals.map(g=>`${escape(g.key)} ${escape(g.before)} → ${escape(g.after)}`).join(' · '):'无'}。共享块独立化 ${diff.patterns.detached} 个；源库与音乐是否更好，需要自行审核，不能用音符数量判断。</div></div>`,'<button class="accent" id="shelf-back">返回候选架</button>');$('#shelf-back').onclick=shelf}
 function comparison(aId,bId){if(aId===bId)throw Error('请选择两版不同的候选');const a=store.get(aId),b=store.get(bId),report=candidateComparisonReport(a,b),diff=report.differences;
  modal('候选 A/B · 不改工作区',`<div class="candidate-shelf-form"><p>同一原稿：<strong>${escape(a.before.name)}</strong> · ${a.before.bars} 小节。下方数字从 A 到 B，不是从当前工作区到 B。</p><div class="candidate-pair"><article><span class="eyebrow">A · 比较起点</span><h3>${escape(a.label)}</h3><p>${source(a)} · ${escape(a.context.scopeLabel)}</p><small>${escape(parameters(a))}</small></article><article><span class="eyebrow">B · 比较目标</span><h3>${escape(b.label)}</h3><p>${source(b)} · ${escape(b.context.scopeLabel)}</p><small>${escape(parameters(b))}</small></article></div><div class="version-stats"><span>${diff.notesBefore} → ${diff.notesAfter} 音符</span><span>${diff.changedTracks} 轨变化</span><span>＋${diff.added} / －${diff.removed} / 修改 ${diff.modified}</span></div>${rows(diff)}<div class="modal-notice">同音高与拍位置配对；不同 ID 不算变化。移调 / 移位计删除＋新增，修改含长度 / 力度 / 微偏移。全局变化 ${diff.globals.length} 项、音色变化 ${diff.soundChanges} 轨。没有自动推荐“最佳”，没有播放，未应用。</div><div id="shelf-error" class="export-progress" role="status"></div></div>`,`<button class="quiet" id="shelf-back">返回候选架</button><button class="quiet" id="download-comparison">下载对比报告</button><button class="accent" id="choose-comparison-b" ${candidateMatches(b,getProject())?'':'disabled'}>打开 B 为候选</button>`);$('#shelf-back').onclick=shelf;$('#download-comparison').onclick=()=>download(JSON.stringify(report,null,2),'sprout-candidate-comparison.json','application/json');$('#choose-comparison-b').onclick=()=>{try{stageSaved(b.id)}catch(e){$('#shelf-error').textContent=e.message}};
 }
 function rename(id){const c=store.get(id);modal('候选改名 · 不改音乐',`<div class="candidate-shelf-form"><label for="shelf-name" class="modal-label">名称</label><input id="shelf-name" maxlength="60" value="${escape(c.label)}"><div id="shelf-error" class="export-progress" role="status"></div></div>`,'<button class="quiet" id="shelf-back">取消</button><button class="accent" id="shelf-rename-save">保存名称</button>');$('#shelf-back').onclick=shelf;$('#shelf-rename-save').onclick=async()=>{try{await store.rename(id,$('#shelf-name').value);changed();shelf()}catch(e){$('#shelf-error').textContent=e.message}}}
 function keep(){const result=getCandidate();if(!result)return;modal('保留候选 · 工作区不变',`<div class="candidate-shelf-form"><p>保留这版的完整音符、原稿、描述、范围与参数，之后可返回比较。不会应用或播放。存储成功后才标记保留。</p><label class="modal-label" for="shelf-name">候选名称</label><input id="shelf-name" maxlength="60" value="${escape(result.label||'我的候选')}"><div id="shelf-error" class="export-progress" role="status"></div></div>`,'<button class="quiet" data-close>取消</button><button class="accent" id="shelf-keep-save">保存到候选架</button>');$('#shelf-keep-save').onclick=async()=>{const b=$('#shelf-keep-save');b.disabled=true;try{const c=normalizeCandidate({...result,label:$('#shelf-name').value});await store.saveMany([c]);if(getCandidate()===result)result.label=c.label;changed();$('#modal').close();toast('候选已写入本机候选架，工作区没有被替换。')}catch(e){$('#shelf-error').textContent=e.message;b.disabled=false}}}
 function alternatives(){if(isBusy())return;const before=copy(getProject()),context=getContext(),controls=normalizeControls(getControls()||{},before.seed>>>0),prompt=$('#prompt-input').value.trim()||'按当前风格，生成一版新的编曲';
  modal('同一原稿 · 规则引擎出三版',`<div class="candidate-shelf-form"><p>以当前工作区为共同起点，保留 <strong>A 留白 / B 适中 / C 活力</strong> 三版。仅用本机音乐规则，不调用任何 LLM，即使助手设置了模型服务。不会应用或开始播放。</p><p>固定范围：<strong>${escape(context.scopeLabel)}</strong>。仅填写已有音块；局部范围保留全局、其他轨道和时间。描述中的范围限制仍由规则处理。</p><label class="modal-label" for="alternatives-prompt">这组编曲描述</label><textarea id="alternatives-prompt" rows="3" maxlength="1600">${escape(prompt)}</textarea><label class="modal-label" for="alternatives-seed">共同变奏种子（B / C 依次加 1）</label><input id="alternatives-seed" type="number" min="0" max="4294967295" step="1" value="${controls.seed}"><div class="candidate-preset-explain"><span>A · 密度 20 / 复杂 15 / 能量 30</span><span>B · 密度 50 / 复杂 35 / 能量 50</span><span>C · 密度 80 / 复杂 80 / 能量 75</span></div><div class="modal-notice">本次三版明确使用上述预设，而不是原调色盘的密度 / 复杂度 / 能量；沿用和声进行与声部连接。人性化分别 20 / 15 / 25。不会更改你的调色盘设置。相同输入 / 种子可复现音符内容，ID 独立分配。不保证三版不同，也不把更多音符称为更好。候选架上限 6 版 / 8 MiB；这组三版要么全部存入，要么全部拒绝。</div><div id="shelf-error" class="export-progress" role="status"></div></div>`,'<button class="quiet" data-close>取消</button><button class="accent" id="alternatives-create">生成并保留三版（仅规则）</button>');$('#alternatives-create').onclick=async()=>{const button=$('#alternatives-create');button.disabled=true;setBusy(true);refresh();try{if(projectFingerprint(before)!==projectFingerprint(getProject()))throw Error('工程已改变，请重新打开三版生成窗口');const candidates=createOfflineAlternatives(before,$('#alternatives-prompt').value,{...context,controls:{...controls,seed:+$('#alternatives-seed').value}});await store.saveMany(candidates);changed();if(candidateMatches(candidates[0],getProject()))stage(candidates[0]);shelf();toast('三版已保留，当前工程没有改变。可先对比，再打开一版为候选。')}catch(e){const error=$('#shelf-error');if(error)error.textContent=e.message;else toast(e.message);button.disabled=false}finally{setBusy(false);refresh()}};
 }
 $('#candidate-shelf').onclick=shelf;$('#generate-alternatives').onclick=()=>{try{alternatives()}catch(e){toast(e.message)}};
 return{refresh,shelf,keep,alternatives};
}
